function svgFlag(string $code): string {
    return match(strtoupper($code)) {
        'VN' => '<svg width="20" height="14" viewBox="0 0 30 20" style="border-radius:3px;box-shadow:0 1px 2px rgba(0,0,0,0.15);flex-shrink:0;"><rect width="30" height="20" fill="#da251d"/><polygon points="15,4 17.35,11.2 11.2,6.75 18.8,6.75 12.65,11.2" fill="#ff0"/></svg>',
        'US' => '<svg width="20" height="14" viewBox="0 0 30 20" style="border-radius:3px;box-shadow:0 1px 2px rgba(0,0,0,0.15);flex-shrink:0;"><rect width="30" height="20" fill="#b22234"/><rect y="2.3" width="30" height="1.5" fill="#fff"/><rect y="5.4" width="30" height="1.5" fill="#fff"/><rect y="8.5" width="30" height="1.5" fill="#fff"/><rect y="11.5" width="30" height="1.5" fill="#fff"/><rect y="14.6" width="30" height="1.5" fill="#fff"/><rect y="17.7" width="30" height="1.5" fill="#fff"/><rect width="12" height="10.8" fill="#3c3b6e"/></svg>',
        'JP' => '<svg width="20" height="14" viewBox="0 0 30 20" style="border-radius:3px;border:1px solid #e2e8f0;box-shadow:0 1px 2px rgba(0,0,0,0.15);flex-shrink:0;"><rect width="30" height="20" fill="#ffffff"/><circle cx="15" cy="10" r="5.5" fill="#bc002d"/></svg>',
        'KR' => '<svg width="20" height="14" viewBox="0 0 30 20" style="border-radius:3px;border:1px solid #e2e8f0;box-shadow:0 1px 2px rgba(0,0,0,0.15);flex-shrink:0;"><rect width="30" height="20" fill="#ffffff"/><circle cx="15" cy="10" r="5" fill="#cd2e3a"/><path d="M15,15 A5,5 0 0,0 15,5 A2.5,2.5 0 0,0 15,10 A2.5,2.5 0 0,1 15,15 Z" fill="#0047a0"/></svg>',
        default => svgIcon('globe', '', 16)
